package com.ecole.gestion_scolaire.hr.service; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import java.time.Year; @Service public class EmployeeNumberGenerator { private final JdbcTemplate jdbc; public EmployeeNumberGenerator(JdbcTemplate jdbc){this.jdbc=jdbc;} public String next(){Long n=jdbc.queryForObject("SELECT nextval('employee_number_seq')",Long.class); return "EMP-"+Year.now().getValue()+"-"+String.format("%06d",n);} }